    parsed = urlparse.urlsplit(uri)

    # Scheme must be present and non-empty
    scheme = parsed.scheme
    if not scheme:
        raise ValueError('uri has no scheme')

    # Normalize scheme to lowercase
    scheme = scheme.lower()

    # Determine the host (netloc without port)
    if host is not None:
        # Use the provided host override
        netloc = host
        # Parse port from the provided host if present
        # The host parameter may contain a port
        if ':' in netloc:
            # Could be host:port or IPv6
            # Try to split host and port
            # But we need to handle IPv6 addresses like [::1]:8080
            if netloc.startswith('['):
